 use serde :: { Deserialize , Serialize } ; use std :: collections :: HashMap ; fn count_crates (path : & PathBuf) -> Result < usize > { let mut count = 0 ; let mut dirs_scanned = 0 ; println ! ("🔍 Scanning: {}" , path . display ()) ; if path . join ("Cargo.toml") . exists () && path . join ("src/lib.rs") . exists () { count += 1 ; println ! ("📦 Found crate: {}" , path . display ()) ; } if let Ok (entries) = fs :: read_dir (path) { for entry in entries { if let Ok (entry) = entry { let entry_path = entry . path () ; if entry_path . is_dir () && ! entry_path . is_symlink () { let name = entry_path . file_name () . unwrap () . to_string_lossy () ; if ! name . starts_with ('.') && name != "target" && name != "node_modules" { dirs_scanned += 1 ; println ! ("📁 Entering: {}" , entry_path . display ()) ; count += count_crates (& entry_path) ? ; } } } } } Ok (count) }